using Xunit;
using System.Text.Json;
using ReviveOS.CloudEngine;
using ReviveOS.Core;
public class AnonymousNotebookTests {
 [Fact] public async Task NotebookExecutesOnCsvAndDxfAndExportsMatchingHash(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var notebook=AnonymousNotebook.Notebook();using var document=JsonDocument.Parse(notebook);Assert.Equal(4,document.RootElement.GetProperty("nbformat").GetInt32());var code=string.Join("\n",document.RootElement.GetProperty("cells").EnumerateArray().Where(x=>x.GetProperty("cell_type").GetString()=="code").Select(x=>string.Concat(x.GetProperty("source").EnumerateArray().Select(y=>y.GetString()))));var script=Path.Combine(root,"notebook.py");await File.WriteAllTextAsync(script,code);await File.WriteAllTextAsync(Path.Combine(root,"entrada.csv"),"x,y\n1,2\n3,4\n");await File.WriteAllTextAsync(Path.Combine(root,"entrada.dxf"),"0\nSECTION\n2\nENTITIES\n0\nLINE\n10\n1\n0\nCIRCLE\n40\n2\n0\nENDSEC\n0\nEOF\n");var wrapper=Path.Combine(root,"runner.py");await File.WriteAllTextAsync(wrapper,"import os,runpy\nos.chdir("+JsonSerializer.Serialize(root)+")\nrunpy.run_path("+JsonSerializer.Serialize(script)+",run_name='__main__')\n");var result=await Commands.Run(OperatingSystem.IsWindows()?"python":"python3",[wrapper]);Assert.Equal(0,result.ExitCode);var output=Assert.Single(Directory.GetFiles(root,"reviveos-resultado-*.json"));using var data=JsonDocument.Parse(await File.ReadAllTextAsync(output));Assert.Equal(2,data.RootElement.GetProperty("csv").GetProperty("linhas_sem_cabecalho").GetInt32());Assert.Equal(1,data.RootElement.GetProperty("dxf").GetProperty("entidades_por_tipo").GetProperty("LINE").GetInt32());var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(await File.ReadAllBytesAsync(output))).ToLowerInvariant();Assert.StartsWith(hash,await File.ReadAllTextAsync(output+".sha256"));}finally{Directory.Delete(root,true);}}
 [Fact] public async Task SaveDoesNotOverwriteExistingFile(){var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".ipynb");try{await File.WriteAllTextAsync(path,"preserve");await Assert.ThrowsAsync<IOException>(()=>AnonymousNotebook.Save(path));Assert.Equal("preserve",await File.ReadAllTextAsync(path));}finally{File.Delete(path);}}
}
